const shell=(inside)=>`<svg viewBox="0 0 360 240" fill="none" xmlns="http://www.w3.org/2000/svg"><ellipse cx="180" cy="213" rx="112" ry="9" fill="#dce4da"/>${inside}</svg>`;
const wheel=(x,y)=>`<circle cx="${x}" cy="${y}" r="10" fill="#53666a"/><circle cx="${x}" cy="${y}" r="4" fill="#bdc9c7"/>`;
const art={bed:shell(`<path d="M75 150v47m207-50v50M90 174h180" stroke="#a5b6b5" stroke-width="9"/>${wheel(75,204)}${wheel(282,204)}<path d="M60 137l76-40 158 28-70 43z" fill="#c9d5d2"/><path d="M66 125l77-48 152 36-72 43z" fill="#fdfefb"/><path d="M66 125l77-48 6 34-69 39z" fill="#dce9e3"/><path d="M149 111l74 45 72-43" stroke="#c4d9d2" stroke-width="3"/><path d="M59 116v45l34 8v-48m184-30v47l30-18V80" stroke="#93aaa9" stroke-width="8" stroke-linecap="round"/><path d="M96 132v31l73 17v-32" stroke="#c8d5d1" stroke-width="6"/><path d="M113 118l37-23 42 10-33 25z" fill="#edf3ee"/>`),monitor:shell(`<path d="M177 144v54m-48 9h96" stroke="#aabbb7" stroke-width="10" stroke-linecap="round"/><rect x="80" y="42" width="205" height="120" rx="12" fill="#d4dfda"/><rect x="88" y="49" width="188" height="97" rx="6" fill="#263e3e"/><path d="M99 83h19l9-12 9 29 12-44 11 34h37m-98 29h15l8-12 8 18 10-25 10 18h45" stroke="#7dd49a" stroke-width="2"/><text x="215" y="85" fill="#8ae2a3" font-size="25" font-family="sans-serif">78</text><text x="215" y="118" fill="#f2cd74" font-size="18" font-family="sans-serif">98</text><circle cx="262" cy="154" r="3" fill="#539b78"/>`),chair:shell(`<circle cx="142" cy="163" r="47" stroke="#566d6d" stroke-width="9"/><circle cx="142" cy="163" r="35" stroke="#abbdb6" stroke-width="2"/><path d="M142 128v70m-33-35h68m-60-26l50 52m-50 0l50-52" stroke="#a3b6ae" stroke-width="2"/><path d="M140 80v70h80l30 42h29m-134-49l-28-81h-17m43 52h83m-7 32v58" stroke="#8a9f9b" stroke-width="7" stroke-linecap="round"/><path d="M135 69h57v67h-38z" fill="#285d4c"/><path d="M156 137h69v15h-69z" fill="#224e40"/><path d="M174 114h56" stroke="#314e44" stroke-width="9" stroke-linecap="round"/>${wheel(230,205)}`),stethoscope:shell(`<path d="M115 48v42c0 62 97 62 97 0V48" stroke="#b6c8c2" stroke-width="10"/><path d="M116 73v28c0 44 96 44 96 0V73" stroke="#265d4a" stroke-width="12"/><path d="M163 135v27c0 57 90 56 90 5v-18" stroke="#265d4a" stroke-width="10"/><circle cx="252" cy="139" r="26" fill="#8fa9a1"/><circle cx="252" cy="139" r="19" fill="#dae5dd"/><circle cx="252" cy="139" r="12" fill="#c1d3c9"/><path d="M114 43l11-9m87 9l-10-9" stroke="#3d6052" stroke-width="10" stroke-linecap="round"/>`),table:shell(`<path d="M102 129v71m152-71v71m-152-34h152" stroke="#a3b3ae" stroke-width="9"/><path d="M76 102l62-35 144 35-62 41z" fill="#2d6853"/><path d="M76 102v23l145 41 61-40v-24l-62 41z" fill="#164c3b"/><path d="M136 64l60 14-50 35-61-15z" fill="#3b7862"/><path d="M110 197h-19m155 0h18" stroke="#536e61" stroke-width="8" stroke-linecap="round"/>`),iv:shell(`<path d="M180 40v159m-45 10l45-13 46 13m-46-13l-6 20" stroke="#a5b8b1" stroke-width="6" stroke-linecap="round"/><path d="M144 55v-13h73v13" stroke="#9bafa8" stroke-width="5" stroke-linecap="round"/><path d="M142 58v13m75-13v13" stroke="#8ca69b" stroke-width="3"/><rect x="125" y="70" width="35" height="58" rx="7" fill="#d0e3d5" stroke="#afc9b8" stroke-width="2"/><path d="M130 93h25v28h-25z" fill="#a3cfb7"/><path d="M143 129v25c0 20 24 15 24 34" stroke="#9abbac" stroke-width="2"/><rect x="203" y="71" width="29" height="49" rx="7" fill="#e3ebe1" stroke="#afc9b8" stroke-width="2"/>${wheel(134,212)}${wheel(226,212)}${wheel(174,217)}`)};
const products=[{name:'Hospital beds',category:'Patient care',sub:'Comfort at the center of care',art:'bed',description:'Explore patient bed options for inpatient and care environments. Discuss positioning, dimensions, rail options, mattress compatibility, and room requirements with your supplier.'},{name:'Patient monitors',category:'Diagnostics',sub:'A clearer view of patient care',art:'monitor',description:'Discuss monitoring requirements for your clinical setting, including the parameters needed, display format, accessories, and compatibility with your existing workflow.'},{name:'Wheelchairs',category:'Mobility',sub:'Support for everyday movement',art:'chair',description:'Explore mobility equipment based on the user and environment. Confirm dimensions, weight capacity, seating, footrests, and transport requirements with your supplier.'},{name:'Diagnostic essentials',category:'Diagnostics',sub:'Tools for everyday assessment',art:'stethoscope',description:'Build an inquiry for everyday assessment equipment, including stethoscopes and related diagnostic tools. Specify intended use and preferred models in your request.'},{name:'Examination tables',category:'Patient care',sub:'A foundation for patient comfort',art:'table',description:'Explore examination furniture for your consulting or treatment space. Discuss dimensions, upholstery, access, positioning, and cleaning requirements.'},{name:'IV stands & accessories',category:'Clinical essentials',sub:'Practical support for care teams',art:'iv',description:'Discuss IV stand configurations and care accessories. Confirm base style, mobility, hook configuration, and compatibility with your clinical requirements.'}];
const selected=new Set();const grid=document.querySelector('#products');let timer;
function render(filter='all'){grid.innerHTML=products.map((p,i)=>filter==='all'||p.category===filter?`<article class="product"><a class="product-visual" href="#equipment" data-detail="${i}" aria-label="View ${p.name}"><span class="tag">${p.category}</span>${art[p.art]}</a><div class="product-info"><p>${p.category}</p><button class="details-link" data-detail="${i}"><h3>${p.name}</h3></button><small>${p.sub}</small><button data-add="${i}" aria-label="Add ${p.name} to inquiry">${selected.has(i)?'✓':'↗'}</button></div></article>`:'').join('')}
function update(){document.querySelector('#count').textContent=`${selected.size} ${selected.size===1?'item':'items'}`;document.querySelector('#selection').innerHTML=selected.size?[...selected].map(i=>`<span class="selected">${products[i].name}<button data-remove="${i}" aria-label="Remove ${products[i].name}">×</button></span>`).join(''):'Select equipment above, or describe what you need below.';render(document.querySelector('.filters .active').dataset.filter)}
function add(i){selected.add(i);update();const toast=document.querySelector('#toast');toast.textContent=`${products[i].name} added to your inquiry`;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.filters .active').classList.remove('active');b.classList.add('active');render(b.dataset.filter)}));
document.addEventListener('click',e=>{const a=e.target.closest('[data-add]');if(a)add(Number(a.dataset.add));const r=e.target.closest('[data-remove]');if(r){selected.delete(Number(r.dataset.remove));update()}const d=e.target.closest('[data-detail]');if(d){e.preventDefault();const i=Number(d.dataset.detail),p=products[i];document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">${p.category}</div><h2>${p.name}</h2><div class="product-visual">${art[p.art]}</div><p>${p.description}</p><small>Illustrative category image. Specific models and availability must be confirmed with your supplier.</small><br><button class="button" id="detail-add">Add to inquiry <span>↗</span></button>`;document.querySelector('#detail-add').onclick=()=>{add(i);document.querySelector('#details').close()};document.querySelector('#details').showModal()}});
document.querySelector('.close').onclick=()=>document.querySelector('#details').close();document.querySelector('#details').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});
document.querySelector('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const content=`EQUIPMENT INQUIRY\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nOrganization: ${data.get('organization')||'Not specified'}\n\nEquipment of interest:\n${[...selected].map(i=>'- '+products[i].name).join('\n')||'See requirements below'}\n\nRequirements:\n${data.get('message')}\n\nPrepared with the Vitalis concept showroom. No inquiry has been sent.`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='equipment-inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your inquiry is ready. Share the downloaded file with your equipment supplier.'});render();
